-- Move every IDENTITY sequence past the highest seeded key so live inserts never collide.
ALTER TABLE category MODIFY (category_id GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE app_user MODIFY (user_id GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE product MODIFY (product_id GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE product_sustainability MODIFY (sustainability_id GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE cart MODIFY (cart_id GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE cart_item MODIFY (cart_item_id GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE customer_order MODIFY (order_id GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE order_item MODIFY (order_item_id GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE payment MODIFY (payment_id GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE review MODIFY (review_id GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
